1	import { supabase } from "@/lib/supabase";
2	import { FRICTION_COLUMNS, RUN_COLUMNS, RUN_COLUMNS_BEFORE_FINDINGS, STEP_COLUMNS } from "@/lib/types";
3	
4	const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
5	const NO_STORE = { "Cache-Control": "no-store" };
6	
7	function fail(status: number, error: string, message: string) {
8	  return Response.json({ error, message }, { status, headers: NO_STORE });
9	}
10	
11	export async function GET(_request: Request, ctx: RouteContext<"/api/runs/[id]">) {
12	  const { id } = await ctx.params;
13	  if (!UUID.test(id)) return fail(404, "not_found", "We couldn't find that run.");
14	
15	  // Only selected columns: the visitor's IP hash and the raw worker error stay private.
16	  const db = supabase();
17	  const [firstRun, steps, frictions] = await Promise.all([
18	    db.from("runs").select(RUN_COLUMNS).eq("id", id).maybeSingle(),
19	    db.from("steps").select(STEP_COLUMNS).eq("run_id", id).order("idx"),
20	    db.from("frictions").select(FRICTION_COLUMNS).eq("run_id", id).order("step_idx").order("id"),
21	  ]);
22	
23	  // PostgREST says a column is missing (42703 or PGRST204) when supabase/schema.sql has not been re-run
24	  // since the report writer was added: read the run without the newest columns rather than fail.
25	  let runError = firstRun.error;
26	  let runRow: Record<string, unknown> | null = firstRun.data;
27	  if (runError && /42703|PGRST204|column/i.test(`${runError.code} ${runError.message}`)) {
28	    const older = await db.from("runs").select(RUN_COLUMNS_BEFORE_FINDINGS).eq("id", id).maybeSingle();
29	    runError = older.error;
30	    runRow = older.data ? { ...(older.data as unknown as Record<string, unknown>), access_mode: null, findings: null } : null;
31	  }
32	
33	  const error = runError ?? steps.error ?? frictions.error;
34	  if (error) {
35	    console.error("Reading run failed:", error.message);
36	    return fail(500, "server_error", "Something went wrong on our side. Retrying shortly.");
37	  }
38	  if (!runRow) return fail(404, "not_found", "We couldn't find that run.");
39	
40	  // A failed run's reason is an internal error message (API or browser failure), not a finding.
41	  const runData = runRow.status === "failed" ? { ...runRow, reason: null } : runRow;
42	
43	  // Check again: the original this run re-checks, and this run's latest re-check. Either query failing
44	  // (an older schema) just leaves the link out.
45	  let original: unknown = null;
46	  let latestRetest: unknown = null;
47	  if (typeof runRow.retest_of === "string") {
48	    const found = await db.from("runs").select("id, status, outcome, verdict").eq("id", runRow.retest_of).maybeSingle();
49	    original = found.error ? null : found.data;
50	  }
51	  const latest = await db
52	    .from("runs")
53	    .select("id, status, outcome, verdict")
54	    .eq("retest_of", id)
55	    .order("created_at", { ascending: false })
56	    .limit(1);
57	  if (!latest.error && latest.data && latest.data.length > 0) latestRetest = latest.data[0];
58	  return Response.json(
59	    { run: runData, steps: steps.data, frictions: frictions.data, original, latest_retest: latestRetest },
